package com.tecsup.model; import jakarta.persistence.*; @Entity public class Categoria { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; public Long getId(){return id;} public void setId(Long v){id=v;}  private String nombre; public String getNombre(){return nombre;} public void setNombre(String v){this.nombre=v;} private String estado; public String getEstado(){return estado;} public void setEstado(String v){this.estado=v;} }
